import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import {validateManifest,inspectAsset,createInstances,drawnBounds} from './assets.js';
const context={console};vm.createContext(context);vm.runInContext(fs.readFileSync(new URL('./vendor/three-r128.min.js',import.meta.url),'utf8'),context);const THREE=context.THREE;
const asset={id:'chair',targetSize:[1,2,1],instances:[{position:[2,0,1]},{position:[-2,0,1],rotation:[0,Math.PI,0]}]};
validateManifest({assets:[asset]});
for(const invalid of [{assets:null},{assets:[asset,asset]},{assets:[{...asset,fit:'squash'}]},{assets:[{...asset,targetSize:[0,1,1]}]},{assets:[{...asset,sourceRotation:[0,NaN,0]}]},{assets:[{...asset,instances:[{scale:[1,NaN,1]}]}]}])assert.throws(()=>validateManifest(invalid));
const material=new THREE.MeshStandardMaterial({color:0xc09965,metalness:.92,roughness:.27});
const texture=new THREE.Texture({width:2048,height:2048});material.map=texture;
const source=new THREE.Group(),mesh=new THREE.Mesh(new THREE.BoxGeometry(2,4,2),material);mesh.position.y=2;source.add(mesh);
const originalPosition=mesh.geometry.attributes.position.array.slice(),originalPBR=JSON.stringify(inspectAsset(source).materials);
const group=createInstances(THREE,source,asset);group.updateMatrixWorld(true);
const meshes=[];group.traverse(o=>{if(o.isMesh)meshes.push(o);});
assert.equal(meshes.length,2);assert.equal(meshes[0].geometry,mesh.geometry);assert.equal(meshes[1].geometry,mesh.geometry);assert.equal(meshes[0].material,material);assert.equal(meshes[1].material.map,texture);
assert.deepEqual(mesh.geometry.attributes.position.array,originalPosition);assert.equal(JSON.stringify(inspectAsset(source).materials),originalPBR);
const bounds=new THREE.Box3().setFromObject(group.children[0]);assert.deepEqual(Array.from(bounds.getSize(new THREE.Vector3()).toArray()),[1,2,1]);assert.equal(bounds.min.y,0);assert.equal(bounds.getCenter(new THREE.Vector3()).x,2);
const stretched=createInstances(THREE,source,{...asset,fit:'axisScale',targetSize:[8,.12,7],instances:[{}]});
const size=new THREE.Box3().setFromObject(stretched).getSize(new THREE.Vector3());assert(Math.abs(size.y-.12)<1e-9);assert.equal(size.x,8);assert.equal(size.z,7);
const oriented=createInstances(THREE,source,{id:'oriented',sourceRotation:[0,0,Math.PI/2],targetSize:[2,1,1],instances:[{}]});
const orientedSize=new THREE.Box3().setFromObject(oriented).getSize(new THREE.Vector3());
assert(Math.abs(orientedSize.x-2)<1e-9);assert(Math.abs(orientedSize.y-1)<1e-9);assert(Math.abs(orientedSize.z-1)<1e-9,'Source orientation precedes uniform fitting.');
assert.equal(source.rotation.z,0);assert.deepEqual(mesh.geometry.attributes.position.array,originalPosition,'Source orientation does not bake vertex changes.');
assert.equal(JSON.stringify(inspectAsset(source).materials),originalPBR);
const retained=new THREE.BufferGeometry();retained.setAttribute('position',new THREE.Float32BufferAttribute([0,0,0,1,0,0,0,1,1,0,-100,0],3));retained.setIndex([0,1,2]);
const retainedMesh=new THREE.Mesh(retained,material),active=drawnBounds(THREE,retainedMesh);
assert.equal(active.min.y,0,'Unused retained debris vertices must not move the fitted floor origin.');assert.equal(retained.attributes.position.getY(3),-100,'Retained source payload stays unchanged.');
const inventory=inspectAsset(source);assert.equal(inventory.triangles,12);assert.equal(inventory.textures[0].width,2048);assert.equal(inventory.materials[0].metalness,.92);
validateManifest(JSON.parse(fs.readFileSync(new URL('./assets.json',import.meta.url))));
console.log('Asset manifest, source orientation, uniform/explicit axis fitting, original PBR/maps/geometry and instance sharing checks passed.');
